  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "incident_detection_monitoring",
      "mermaid_file": "LegionIncidentResponse/SG-001_incident_detection_monitoring.mmd"
    },
    {
      "id": "SG-002",
      "name": "failed_remediation_protocol",
      "mermaid_file": "LegionIncidentResponse/SG-002_failed_remediation_protocol.mmd"
    },
